export interface IPDResult {
  ipdMm: number; // Final average
  limbusDistanceMm: number;
  pupilDistanceMm: number;
  confidence: number;
  rightOuterLimbus: [number, number]; // [x, y] in percentage or normalized
  leftInnerLimbus: [number, number];
  rightPupilCenter: [number, number];
  leftPupilCenter: [number, number];
  cardCorners?: [number, number][]; // Coordinates for the calibration card
  pixelDistanceLimbus: number;
  pixelDistancePupil: number;
  scalingFactor: number;
  calibrationUsed: 'card' | 'average_iris' | 'estimation';
  explanation: string;
}

export type ScanStatus = 'idle' | 'capturing' | 'analyzing' | 'completed' | 'error';

import { GoogleGenAI, Type } from "@google/genai";
import { IPDResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export async function analyzeIPD(base64Image: string): Promise<IPDResult> {
  const model = ai.models.generateContent({
    model: 'gemini-3-pro-preview', // Using Pro for higher geometric precision
    contents: [
      {
        parts: [
          {
            text: `Act as a specialized clinical ophthalmic AI. Your objective is to calculate the Interpupillary Distance (IPD) from the provided image.

CALIBRATION RULES:
1. Search for a standard ID/Credit card (85.6mm width). 
2. If found, use its width to establish the mm/pixel scaling factor.
3. If no card is found, use the standard adult iris diameter (11.7mm) as the reference.
4. If neither is clear, use a demographic estimation (scaling factor derived from average inter-ocular distance).

MEASUREMENT PROTOCOL:
- Landmark 1: Right Eye Outer Limbus (The border between the white sclera and the iris on the ear-side of the right eye).
- Landmark 2: Left Eye Inner Limbus (The border between the white sclera and the iris on the nose-side of the left eye).
- Landmark 3: Right Eye Pupil Center.
- Landmark 4: Left Eye Pupil Center.

CALCULATION:
- IPD_Limbus = Euclidean distance(L1, L2) * scaling_factor.
- IPD_Pupil = Euclidean distance(L3, L4) * scaling_factor.
- Resulting IPD = Average(IPD_Limbus, IPD_Pupil).

OUTPUT FORMAT:
Return a JSON object with precise coordinates (0-1000 scale, where 0,0 is top-left and 1000,1000 is bottom-right).
Include cardCorners if a card was used.`
          },
          {
            inlineData: {
              mimeType: "image/jpeg",
              data: base64Image
            }
          }
        ]
      }
    ],
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          ipdMm: { type: Type.NUMBER, description: "Final calculated IPD in mm" },
          limbusDistanceMm: { type: Type.NUMBER },
          pupilDistanceMm: { type: Type.NUMBER },
          pixelDistanceLimbus: { type: Type.NUMBER },
          pixelDistancePupil: { type: Type.NUMBER },
          scalingFactor: { type: Type.NUMBER, description: "mm per pixel" },
          confidence: { type: Type.NUMBER, description: "0.0 to 1.0 confidence score" },
          rightOuterLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER }, description: "[x, y] coordinates" },
          leftInnerLimbus: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          rightPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          leftPupilCenter: { type: Type.ARRAY, items: { type: Type.NUMBER } },
          cardCorners: { 
            type: Type.ARRAY, 
            items: { type: Type.ARRAY, items: { type: Type.NUMBER } },
            description: "Optional list of 4 [x, y] points for the card corners"
          },
          calibrationUsed: { type: Type.STRING, description: "card, average_iris, or estimation" },
          explanation: { type: Type.STRING }
        },
        required: ["ipdMm", "limbusDistanceMm", "pupilDistanceMm", "rightOuterLimbus", "leftInnerLimbus", "rightPupilCenter", "leftPupilCenter", "scalingFactor", "explanation", "calibrationUsed"]
      }
    }
  });

  const response = await model;
  const result = JSON.parse(response.text || "{}");

  return result as IPDResult;
}

